aa_case('VAS all auto mixed endpoints decimal and clear explicit',function(){$d=aa_one('vas');$p=&$d['elements'][0]['properties'];D::validate($d);aa_assert($p['label_settings'][2]['position']===1.8);foreach($p['label_settings'] as &$l)$l['position']=null;unset($l);D::validate($d);$p['label_settings'][1]['position']=0.13;D::validate($d);});
aa_case('VAS mobile layout and label planes roundtrip without changing scalar answers',function(){$d=aa_one('vas');$p=&$d['elements'][0]['properties'];$p+=array('label_placement'=>'alternate','edge_spacing'=>'custom','edge_margin'=>18,'mobile_orientation'=>'vertical','vertical_top'=>'min','vertical_height'=>360);$n=D::validate($d);aa_assert($n['elements'][0]['properties']===$p);foreach(array('label_placement'=>'diagonal','edge_spacing'=>'unsafe','edge_margin'=>-1,'mobile_orientation'=>'diagonal','vertical_top'=>'left','vertical_height'=>601) as $key=>$v){$bad=$d;$bad['elements'][0]['properties'][$key]=$v;aa_reject(function()use($bad){D::validate($bad);});}});
aa_case('VAS numeric relative label size validates and roundtrips without changing label positions',function(){foreach(array(25,80,100,125,200,300) as $percent){$d=aa_one('vas');$positions=$d['elements'][0]['properties']['label_settings'];$d['elements'][0]['properties']['label_scale']=$percent;$n=D::validate($d);aa_assert($n['elements'][0]['properties']['label_scale']===$percent&&$n['elements'][0]['properties']['label_settings']===$positions);}foreach(array(0,24,301,1.5,'100',null) as $bad){$d=aa_one('vas');$d['elements'][0]['properties']['label_scale']=$bad;aa_reject(function()use($d){D::validate($d);});}});
aa_case('VAS positions finite bounded typed and label IDs unique',function(){foreach(array(-3,8,'1',INF,NAN) as $v){$d=aa_one('vas');$d['elements'][0]['properties']['label_settings'][0]['position']=$v;aa_reject(function()use($d){D::validate($d);});}$d=aa_one('vas');$d['elements'][0]['properties']['label_settings'][1]['id']=$d['elements'][0]['properties']['label_settings'][0]['id'];aa_reject(function()use($d){D::validate($d);});});
aa_case('rich text formatting links images lists remain with safe link policy',function(){$s=H::sanitize('<h2>Título</h2><p><b>B</b><i>I</i><u>U</u><br><a href="https://example.test">L</a></p><ol><li>Item</li></ol><img src="/image.png" alt="Local">');foreach(array('<h2>','<b>','<i>','<u>','<br>','<ol>','<img','noopener noreferrer') as $v)aa_assert(strpos($s,$v)!==false,$v);aa_assert(H::sanitize($s)===$s);aa_assert(H::sanitize('<p><br></p>')==='');});
aa_case('rich text strips scripts events dangerous protocols SVG iframes styles',function(){$s=H::sanitize('<script>alert(1)</script><img src="javascript:alert(1)" onerror="bad()"><a href="jav&#x61;script:alert(2)" onclick="bad()">x</a><iframe src="https://example.test"></iframe><svg onload="bad()"></svg><p style="background:url(javascript:bad())">ok</p>');aa_assert(!preg_match('/<(script|iframe|svg)|onerror=|onclick=|onload=|javascript:|style=/i',$s));});
aa_case('backend sanitizes untrusted HTML on save and load',function()use(&$owned){$d=aa_one('text');$d['id']='AE_'.bin2hex(random_bytes(12));$owned[]=$d['id'];$d['elements'][0]['properties']['footer_html']='<p onclick="bad()">OK</p><iframe></iframe>';R::save($d,0);$r=R::load($d['id']);aa_assert($r['definition']['elements'][0]['properties']['footer_html']==='<p>OK</p>');});
aa_case('variable rename preserves technical IDs response keys and option identities',function(){$d=aa_one('likert');$before=$d['elements'][0];$d['elements'][0]['properties']['variable_name']='ansiedad_VAS';$d['elements'][0]['properties']['label']='Otro label';$n=D::validate($d)['elements'][0];foreach(array('id','response_key','options') as $k)aa_assert($n[$k]===$before[$k]);});
aa_case('variable invalid duplicate and Matrix row conflicts rejected',function(){foreach(array('with space','123bad','área','',str_repeat('a',129)) as $v)aa_bad('text','variable_name',$v);$d=aa_fixture();$d['elements'][1]['properties']['variable_name']=$d['elements'][0]['properties']['variable_name'];aa_reject(function()use($d){D::validate($d);});$d=aa_one('matrix');$d['elements'][0]['properties']['matrix_rows'][0]['variable_name']=$d['elements'][0]['properties']['variable_name'];aa_reject(function()use($d){D::validate($d);});});
aa_case('variable names case sensitive and unique within nested assessment',function(){$d=aa_fixture();$d['elements'][0]['properties']['variable_name']='Edad';$d['elements'][1]['properties']['variable_name']='edad';D::validate($d);});
aa_case('columns typed limited and Select rejects irrelevant columns',function(){foreach(array(0,13,2.5,'3') as $v)aa_bad('single_choice','columns',$v);aa_bad('select','columns',3);foreach(array('single_choice','multiple_choice') as $t){$d=aa_one($t);foreach(array(1,2,3,12) as $v){$d['elements'][0]['properties']['columns']=$v;D::validate($d);}}});
aa_case('nullable string lengths and Unicode letters preset have real consumers',function(){$d=aa_one('text');$p=&$d['elements'][0]['properties'];$p['content_type']='letters';$p['min_length']=null;$p['max_length']=null;aa_assert(!A::errors($d,array('R_text'=>"María José\nÁÉ")));aa_assert(count(A::errors($d,array('R_text'=>'ABC123')))===1);$p['min_length']=3;$p['max_length']=5;aa_assert(count(A::errors($d,array('R_text'=>'AB')))===1);aa_assert(count(A::errors($d,array('R_text'=>'ABCDEF')))===1);});
aa_case('multiline email URL tel validators follow content type',function(){$d=aa_one('textarea');$p=&$d['elements'][0]['properties'];$p['content_type']='email';aa_assert(count(A::errors($d,array('R_textarea'=>'bad')))===1);aa_assert(!A::errors($d,array('R_textarea'=>'a@example.test')));$p['content_type']='url';aa_assert(count(A::errors($d,array('R_textarea'=>'relative')))===1);$p['content_type']='tel';aa_assert(!A::errors($d,array('R_textarea'=>'+54 11')));});
aa_case('integer only numeric rejects fractions but keeps decimal bounds contract',function(){$d=aa_one('number');$d['elements'][0]['properties']['integer_only']=true;aa_assert(count(A::errors($d,array('R_number'=>2.5)))===1);aa_assert(!A::errors($d,array('R_number'=>2)));});
aa_case('Matrix rows retain shared scale and independent numeric responses',function(){$d=aa_one('matrix');$e=$d['elements'][0];$answers=array();foreach($e['properties']['matrix_rows'] as $i=>$r)$answers[$r['response_key']]=$e['options'][$i%4]['id'];aa_assert(!A::errors($d,$answers));foreach($e['properties']['matrix_rows'] as $i=>$r)aa_assert(A::value(array_merge($e,array('type'=>'likert')),$answers[$r['response_key']])===-2+$i%4);});
aa_case('Matrix required all rows optional and individual required semantics',function(){$d=aa_one('matrix');aa_assert(count(A::errors($d,array()))===5);$p=&$d['elements'][0]['properties'];$p['required']=false;aa_assert(count(A::errors($d,array()))===1);$p['matrix_rows'][0]['required']=false;aa_assert(!A::errors($d,array()));});
aa_case('Matrix invalid option object response root unknown row keys rejected',function(){$d=aa_one('matrix');$p=&$d['elements'][0]['properties'];$p['required']=false;$p['matrix_rows'][0]['required']=false;foreach(array('bad',array('id'=>'O_matrix_0'),true) as $v)aa_assert(count(A::errors($d,array('R_ROW_0'=>$v)))===1);aa_assert(count(A::errors($d,array('R_matrix'=>'O_matrix_0')))===1);});
aa_case('Matrix duplicate row IDs keys and variable names rejected',function(){foreach(array('id','response_key','variable_name') as $k){$d=aa_one('matrix');$d['elements'][0]['properties']['matrix_rows'][1][$k]=$d['elements'][0]['properties']['matrix_rows'][0][$k];aa_reject(function()use($d){D::validate($d);});}});
aa_case('Matrix reorder and label rename preserve row response identity',function(){$d=aa_one('matrix');$rows=$d['elements'][0]['properties']['matrix_rows'];$d['elements'][0]['properties']['matrix_rows']=array_reverse($rows);$d['elements'][0]['properties']['matrix_rows'][0]['label']='Renamed';$base=$d['elements'][0]['properties']['variable_name'];foreach($d['elements'][0]['properties']['matrix_rows'] as $i=>&$r)$r['variable_name']=$base.'_'.($i+1);unset($r);$n=D::validate($d);aa_assert($n['elements'][0]['properties']['matrix_rows'][0]['response_key']===$rows[4]['response_key']);});
