aa_case('Matrix Date URL reject mapping explicitly without writes or expansion',function(){$before=count(R::listing());foreach(array('matrix','date','url') as $t)aa_reject(function()use($t){M::map(aa_one($t));});aa_assert(count(R::listing())===$before);});
aa_case('supported Engine snapshots retain rich content variable columns and VAS positions',function(){foreach(array('text','number','single_choice','likert','vas') as $t){$d=aa_one($t);$out=M::map($d)->toArray();aa_assert(D::json($out['protocol_metadata']['native_definition'])===D::json(D::validate($d)));aa_assert(!empty($out['protocol_metadata']['mapping_warnings']));}});
aa_case('JSON roundtrip creates independent draft and preserves authored content',function()use(&$owned){
    $d=aa_fixture();$d['id']='AE_'.bin2hex(random_bytes(12));$owned[]=$d['id'];$saved=R::save($d,0);$file=P::export($d['id'],1);
    aa_assert(array_keys($file)===array('format','version','definition'));$copy=P::import(D::json($file));$owned[]=$copy['definition']['id'];
    aa_assert($copy['revision']===1&&$copy['definition']['id']!==$d['id']);
    $normalize=function($definition){$walk=function(&$items)use(&$walk){foreach($items as &$e){unset($e['id'],$e['response_key']);foreach($e['options'] as &$o)unset($o['id']);unset($o);foreach(array('matrix_rows','label_settings') as $key)if(isset($e['properties'][$key]))foreach($e['properties'][$key] as &$row)unset($row['id'],$row['response_key']);unset($row);$walk($e['children']);}unset($e);};unset($definition['id']);$walk($definition['elements']);foreach($definition['flow']['pages'] as &$page)unset($page['id'],$page['boundary_id']);unset($page);return D::json($definition);};
    aa_assert($normalize($saved['definition'])===$normalize($copy['definition']),'Authored content changed');aa_assert(R::load($d['id'])['revision']===1,'Original changed');
    $again=P::import(D::json($file));$owned[]=$again['definition']['id'];aa_assert($again['definition']['id']!==$copy['definition']['id']);
});
aa_case('JSON rejects malformed unsupported oversized and injected records without writes',function(){
    $n=count(R::listing());$file=array('format'=>P::FORMAT,'version'=>1,'definition'=>aa_fixture());
    $invalid=array('{','[]',str_repeat(' ',P::MAX_BYTES+1));
    foreach(array(array('version'=>2),array('responses'=>array('secret')),array('format'=>'old_form')) as $change)$invalid[]=D::json(array_merge($file,$change));
    foreach($invalid as $json)aa_reject(function()use($json){P::import($json);});
    aa_assert(count(R::listing())===$n);
});
aa_case('JSON export refuses stale revision and import respects authorization',function()use(&$owned){$d=aa_one('text');$d['id']='AE_'.bin2hex(random_bytes(12));$owned[]=$d['id'];R::save($d,0);$json=D::json(P::export($d['id'],1));aa_reject(function()use($d){P::export($d['id'],2);});wp_set_current_user(0);try{aa_reject(function()use($json){P::import($json);});aa_reject(function()use($d){P::export($d['id'],1);});}finally{wp_set_current_user(1);}});
aa_case('Form Library admin surface is retired',function(){global $submenu;do_action('admin_menu');foreach($submenu['eipsi-results-experience']??array() as $item)aa_assert($item[2]!=='edit.php?post_type=eipsi_form_template');$type=get_post_type_object('eipsi_form_template');aa_assert($type&&!$type->show_ui&&!$type->show_in_rest);});
aa_case('Question JSON exports and imports every question type independently without writes',function()use(&$owned){
    $d=aa_fixture();$d['id']='AE_'.bin2hex(random_bytes(12));$owned[]=$d['id'];$record=R::save($d,0);$before=count(R::listing());
    $strip=function($value)use(&$strip){if(!is_array($value))return $value;$out=array();foreach($value as $key=>$v)if(!in_array($key,array('id','response_key'),true))$out[$key]=$strip($v);return $out;};
    foreach($record['definition']['elements'] as $question){if(!in_array($question['type'],D::QUESTIONS,true))continue;$file=P::exportQuestion($d['id'],1,$question['id']);aa_assert(array_keys($file)===array('format','version','question'));$a=P::importQuestion(D::json($file));$b=P::importQuestion(D::json($file));aa_assert($a['id']!==$question['id']&&$b['id']!==$a['id']&&$a['response_key']!==$question['response_key']);aa_assert(D::json($strip($a))===D::json($strip($question)),'Question content changed: '.$question['type']);}
    aa_assert(count(R::listing())===$before,'Question import wrote an assessment');
});
aa_case('Question JSON rejects assessment documents nonquestions and invalid definitions',function()use(&$owned){
    $q=aa_one('number')['elements'][0];$file=array('format'=>P::QUESTION_FORMAT,'version'=>1,'question'=>$q);
    $bad=$file;$bad['question']['properties']['step']=0;
    foreach(array('{',str_repeat(' ',P::MAX_BYTES+1),D::json(array('format'=>P::FORMAT,'version'=>1,'definition'=>aa_fixture())),D::json(array_merge($file,array('version'=>2))),D::json($bad),D::json(array_merge($file,array('answers'=>array())))) as $json)aa_reject(function()use($json){P::importQuestion($json);});
    $d=aa_one('text');$d['id']='AE_'.bin2hex(random_bytes(12));$owned[]=$d['id'];R::save($d,0);aa_reject(function()use($d){P::exportQuestion($d['id'],1,'MISSING');});aa_reject(function()use($d){P::exportQuestion($d['id'],2,$d['elements'][0]['id']);});
});
aa_case('Question JSON import requires administrator authorization',function(){wp_set_current_user(0);try{aa_reject(function(){P::importQuestion('{}');});}finally{wp_set_current_user(1);}});
}finally{wp_set_current_user(1);foreach($owned as $id)delete_option(R::PREFIX.$id);}
echo "$tests tests, $failures failures\n";exit($failures?1:0);
